int build_indirect_sgl(Sg_scatter_hold *schp, Sg_fd *sfp, int buff_size) {
    int ret = 0;
    int k = 0;
    int nsegs = 0;
    int sector_size = 512; // Assuming standard sector size if not provided by context
    unsigned int order = 0;
    int allocated = 0;
    unsigned long flags = 0;

    if (!schp || !sfp || buff_size <= 0) {
        return -EINVAL;
    }

    // Align buffer size to sector size
    buff_size = (buff_size + (sector_size - 1)) & ~(sector_size - 1);

    schp->kern_pages = NULL;
    schp->buff_size = buff_size;
    schp->sgl = NULL;

    while (buff_size > 0) {
        if (k >= SGL_MAX_ELEMENTS) {
            ret = -EINVAL;
            goto error;
        }

        order = get_order(buff_size); // Assume get_order is defined elsewhere

        schp->kern_pages[k] = (void *)__get_free_pages(flags, order);
        if (!schp->kern_pages[k]) {
            if (allocated == 0)
                ret = -ENOMEM;
            goto error;
        }

        buff_size -= (PAGE_SIZE << order);
        schp->sgl[k].page = schp->kern_pages[k];
        schp->sgl[k].length = (PAGE_SIZE << order);
        nsegs++;
        k++;
        allocated++;
    }

    schp->n_elem = nsegs;
    return 0;

error:
    while (--k >= 0) {
        free_pages((unsigned long)schp->kern_pages[k], get_order((PAGE_SIZE << order))));
    }
    return ret;
}

int build_indirect_sgl(Sg_scatter_hold *schp, Sg_fd *sfp, int buff_size) {
    int ret = 0;
    unsigned int nr_sg = 0;
    unsigned int sg_sectors;
    unsigned int max_sg = schp->k_use->max_sg;
    unsigned int buff_sectors;
    unsigned int sectors;
    unsigned int max_order = 0;
    int i;

    if (!buff_size)
        return 0;

    buff_sectors = (buff_size + sfp->device_sectors - 1) / sfp->device_sectors;

    if (buff_sectors > max_sg) {
        ret = -EINVAL;
        goto out;
    }

    schp->k_ref = 0;
    schp->k_nents = 0;
    schp->k_nseg = 0;
    schp->k_size = 0;

    for (i = 0; i < max_sg; ++i) {
        Sg_scat *scp = &schp->k_scat[i];
        struct page *page;
        unsigned int len;

        scp->page = NULL;
        scp->k_use = NULL;
        scp->nalloc = 0;

        if (nr_sg >= buff_sectors)
            break;

        len = sfp->device_sectors - (buff_sectors % sfp->device_sectors);
        if (i == max_sg - 1)
            len = buff_sectors;

        page = alloc_pages(GFP_KERNEL | __GFP_ZERO, max_order);
        if (!page) {
            ret = -ENOMEM;
            goto error;
        }

        scp->page = page;
        scp->nalloc = 1 << max_order;
        scp->k_use = kmalloc(sizeof(*scp->k_use), GFP_KERNEL);
        if (!scp->k_use) {
            __free_pages(page, max_order);
            ret = -ENOMEM;
            goto error;
        }

        scp->k_use->length = len * sfp->device_size;
        scp->k_use->offset = 0;
        scp->k_use->nalloc = 1 << max_order;
        scp->k_use->page = page;

        ++nr_sg;
        schp->k_nents++;
        schp->k_nseg++;
        schp->k_size += len * sfp->device_size;
        buff_sectors -= len;
    }

    if (nr_sg == 0) {
        ret = -ENOMEM;
        goto out;
    }

    schp->k_ref = 1;
    return nr_sg;

error:
    while (nr_sg > 0) {
        --nr_sg;
        Sg_scat *scp = &schp->k_scat[nr_sg];
        if (scp->page)
            __free_pages(scp->page, max_order);
        if (scp->k_use)
            kfree(scp->k_use);
    }
out:
    return ret;
}

#include <linux/gfp.h>
