#include <linux/errno.h>

int build_indirect_scatter_list(Sg_scatter_hold *schp, Sg_fd *sfp, int buff_size) {
    int result = 0;
    int order = get_order(buff_size);
    int gfp_mask = GFP_KERNEL;
    struct page *page = NULL;
    int nr_pages = 1 << order;
    int i;

    if (!buff_size || (buff_size % SECTOR_SIZE)) {
        buff_size = ((buff_size + SECTOR_SIZE - 1) / SECTOR_SIZE) * SECTOR_SIZE;
    }

    for (i = 0; i < nr_pages; i++) {
        page = alloc_pages(gfp_mask, order);
        if (!page) {
            result = -ENOMEM;
            break;
        }

        schp->kern_pages[i] = page;
        schp->nENTS++;
    }

    if (result < 0) {
        while (--i >= 0) {
            __free_pages(schp->kern_pages[i], order);
        }
        return result;
    }

    return 0;
}

int build_indirect_scatter_list(Sg_scatter_hold *schp, Sg_fd *sfp, int buff_size) {
    int ret = 0;
    unsigned int align_size = 0;
    int order = 0;
    struct page *page = NULL;

    if (!schp || !sfp || buff_size <= 0)
        return -EINVAL;

    align_size = ALIGN(buff_size, SECTOR_SIZE);

    if (build_sg_table(schp, sfp, align_size)) {
        ret = -ENOMEM;
        goto out;
    }

    order = get_order(align_size);
    page = alloc_pages(GFP_KERNEL | __GFP_HIGHMEM, order);
    if (!page) {
        ret = -ENOMEM;
        goto out_free_sg;
    }

    schp->kern_pages = page;
    schp->buff_size = align_size;

    return 0;

out_free_sg:
    free_sg_table(schp, sfp);
out:
    return ret;
}

int build_indirect_sg_list(Sg_scatter_hold *schp, Sg_fd *sfp, int buff_size) {
    int ret = 0;
    size_t align_size = ALIGN(buff_size, SECTOR_SIZE);

    if (align_size < buff_size) {
        ret = -ENOMEM;
        return ret;
    }

    ret = sg_build_table(schp, sfp, align_size);
    if (ret < 0) {
        return ret;
    }

    int num_allocs = 0;
    int order = get_order(align_size);
    unsigned long flags = GFP_KERNEL | __GFP_ZERO;

    while (num_allocs < MAX_RETRIES) {
        struct page *page = alloc_pages(flags, order);
        if (!page) {
            if (num_allocs > 0) {
                ret = -ENOMEM;
                break;
            }
            num_allocs++;
            continue;
        }

        // Assume the page is added to the scatter-gather list here
        sg_add_page_to_list(schp, page, align_size);

        // Successfully allocated and added
        break;
    }

    if (ret < 0) {
        // Free any previously allocated pages if error
        sg_free_pages(schp);
    }

    return ret >= 0 ? ret : ret;
}
